"""Post-run integrity/security audit. Never emits credential values."""
import json,hashlib,random,os,subprocess,datetime,xml.etree.ElementTree as ET
from .artifacts import *
from .provider import GOLD_KEYS,FORBIDDEN_FIELDS,all_keys
from .runner import verify_frozen
from .deadline import elapsed

def xml_summary(p):
 root=ET.parse(p).getroot();suites=list(root.iter('testsuite'));return {k:sum(int(s.get(k,0)) for s in suites) for k in ['tests','failures','errors','skipped']}
def run():
 manifest=verify_frozen();state=read(ROOT/'task_state.json');changed=[p for p,h in state['protected_files'].items() if sha(REPO/p)!=h];assert not changed
 selection=read(ROOT/'dataset3_selection_manifest.json');assert sha(ROOT/'dataset3_selection_manifest.json')==manifest['selection_manifest_sha256'];assert selection['indices_zero_based']==random.Random(20261028).sample(range(2366),10)
 lines=(ROOT/'datasets/GaRAGe_benchmark.jsonl').read_bytes().splitlines();assert sha(ROOT/'datasets/GaRAGe_benchmark.jsonl')==manifest['dataset_sha256']
 original=[json.loads(lines[i]) for i in selection['indices_zero_based']];runtime=rows(ROOT/'runtime_inputs.jsonl');requests=rows(ROOT/'api_requests.jsonl');events=rows(ROOT/'api_events.jsonl');results=rows(ROOT/'results.jsonl');assert len(original)==len(runtime)==len(results)==10
 for row,record,entry in zip(runtime,original,selection['records']):
  assert row['case']['query']==record['question'];assert row['query_context']['question_date']==record['question_date'];assert hashlib.sha256(lines[entry['index_zero_based']]).hexdigest()==entry['record_sha256'];assert row['included_count']==len(record['grounding'])==15
  for source,mapping,ground in zip(row['case']['sources'],row['mapping'],record['grounding']):
   raw=source['content'][mapping['metadata_header_characters']:];assert raw==ground[mapping['original_marker']];assert hashlib.sha256(raw.encode()).hexdigest()==mapping['raw_text_sha256']
 violations=[];ids=[r['sample_id'] for r in original];privateids=[s['source_id'] for r in runtime for s in r['case']['sources']]
 for req,event in zip(requests,events):
  payload=req['payload'];user=json.loads(payload['messages'][1]['content']);encoded=json.dumps(payload,ensure_ascii=False);illegal=set(all_keys(user))&(FORBIDDEN_FIELDS|GOLD_KEYS)
  if illegal:violations.append({'attempt':req['attempt'],'forbidden_keys':sorted(illegal)})
  assert all(x not in encoded for x in ids+privateids);assert payload['temperature']==0 and payload['model']=='gpt-4o-mini';assert event['status']=='SUCCESS';assert (event.get('usage') or {})['prompt_tokens']<=req['input_token_upper_bound']<=60000
  assert user['query']==runtime[req['runtime_index']]['case']['query'];assert user['query_context']==runtime[req['runtime_index']]['query_context'];assert len(user['documents'])==15
  if req['kind']=='shared_control':assert 'response_contract' not in user
 for i in range(10):
  group=[r for r in requests if r['runtime_index']==i];users=[json.loads(r['payload']['messages'][1]['content']) for r in group];assert [g['kind'] for g in group]==['semantic_analysis','semantic_cfaf','shared_control'];assert users[0]['documents']==users[1]['documents']==users[2]['documents'];assert users[1]['semantic_assessment']==users[2]['semantic_assessment']
 assert not violations
 audit=read(ROOT/'source_audit.json');audit['original_field_order']=list(json.loads(lines[0]));audit['license']='CC-BY-NC-4.0 (Attribution-NonCommercial 4.0 International)';audit['license_sha256']=sha(ROOT/'local/upstream_LICENSE');audit['publication_url']='https://aclanthology.org/2025.findings-acl.875/';audit['annotation_note']='Exact original strings retained, including OUTDATED, blank correctness/relevance, whitespace and category spelling differences. Tags/comments/reference answers preserved in original ignored records; free-text fields are not normalized into invented classes.';write(ROOT/'source_audit.json',audit)
 supplement=[]
 for entry,record in zip(selection['records'],original):supplement.append({'sample_id':record['sample_id'],'index_zero_based':entry['index_zero_based'],'index_one_based':entry['index_zero_based']+1,'original_metadata':{k:record[k] for k in ['question_date','question_valid','question_false_premise','question_seeking','question_sensitive','question_type','question_complexity','question_category','question_popularity','answer_validate']},'evidence_relevant_counts':{v:record['evidence_relevant'].count(v) for v in sorted(set(record['evidence_relevant']))},'evidence_correct_counts':{v:record['evidence_correct'].count(v) for v in sorted(set(record['evidence_correct']))}})
 write(ROOT/'selection_annotation_supplement.json',supplement)
 write(ROOT/'security_audit.json',{'status':'PASS','audited_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'elapsed_seconds':elapsed(),'protected_files_checked':len(state['protected_files']),'protected_files_changed':changed,'frozen_source_and_runtime_verified':True,'selection_manifest_unchanged':True,'source_checksum_verified':True,'selected_records':10,'retained_passages':150,'omitted_passages':0,'original_question_and_dates_preserved':True,'original_passage_text_hashes_match':True,'actual_payloads_audited':len(requests),'forbidden_field_violations':violations,'selected_sample_ids_in_payloads':False,'private_source_ids_in_payloads':False,'neutral_views_only':True,'shared_semantic_assessment_identical':True,'control_contract_contamination':False,'all_generations_512_analysis_1500':all(r['payload']['max_tokens']==(1500 if r['kind']=='semantic_analysis' else 512) for r in requests),'attempt_cap_respected':len(requests)<=60,'retry_count':0,'input_upper_bounds_verified_against_actual_usage':True,'embeddings_verifiers_case_fact_web_search':0,'original_selector_and_eight_stages_unchanged':True,'all_API_finish_reasons_stop':all(e['finish_reason']=='stop' for e in events),'semantic_valid_count':sum(bool(r['outcome']['semantic_valid']) for r in results),'semantic_invalid_count':sum(not r['outcome']['semantic_valid'] for r in results),'source_role_coverage_failures':sum('SOURCE_ROLE_COVERAGE_INVALID' in r['outcome']['reference_audit']['errors'] for r in results),'source_reference_failures':sum(any('UNKNOWN_SPAN_ID' in e for e in r['outcome']['reference_audit']['errors']) for r in results),'independent_human_review':'PENDING','no_post_result_runtime_changes':True,'runtime_boundary_limitation':'Provider forbidden-key list does not independently list sample_id; exact adapter whitelist and actual serialized identifier scan enforce this pilot boundary. Add explicit key as future defense; frozen provider was not changed.'})
 reg=read(ROOT/'regression_audit.json');reg['xml_summaries']={p.name:xml_summary(p) for p in ROOT.glob('*tests.xml')};reg['protected_current_files_unchanged']=len(state['protected_files']);write(ROOT/'regression_audit.json',reg)
 metric=read(ROOT/'grounding_metrics.json');metric['raw_proposal_warning']='Analyzer support/role metrics include diagnostic proposals from 9 invalid assessments. These are not accepted T3 evidence selections or answer citations. Only 1 assessment is valid; it proposes no global supporting evidence.';metric['semantic_valid_cases']=1;metric['semantic_invalid_cases']=9;metric['public_unsupported_FULL_T3']={'count':0,'FULL_denominator':0,'rate':None,'reason':'No T3 FULL responses; says nothing about ability to answer well-supported requests.'};write(ROOT/'grounding_metrics.json',metric)
 print('AUDIT PASS',len(state['protected_files']),'protected files;',len(requests),'payloads;',sum(r['outcome']['semantic_valid'] for r in results),'valid semantic assessments')
if __name__=='__main__':run()
